-- 1. MAXIMUS — SAT_CHANNEL_DEFINITION   [Implemented]
-- Consecutive versions of a key (per RECORD_SOURCE, by LOAD_DATETIME) must differ in
-- HASHDIFF (unchanged_reinserts) AND in the stored payload itself
-- (unchanged_payload_reinserts -- catches a HASHDIFF that hashes columns this satellite
-- does not store, e.g. a shared stage). standard satellite, automate_dv.sat; PK
-- DISTRIBUTION_CHANNEL_HKEY; 1 RECORD_SOURCE group(s):
-- MAXIMUS_BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW
-- [2 col(s)].
----------------------------------------------------------------------------------------
with base as (
    select DISTRIBUTION_CHANNEL_HKEY, RECORD_SOURCE, LOAD_DATETIME, HASHDIFF_CHANNEL_DEFINITION,
           md5(coalesce(to_varchar(SUBCHANNELCODE), '^^') || '||' || coalesce(to_varchar(SUBCHANNELEFFECTIVEDATE), '^^') || '||') as payload_sig
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_CHANNEL_DEFINITION
     where startswith(RECORD_SOURCE, 'MAXIMUS_')
),
seq as (
    select *,
           lag(HASHDIFF_CHANNEL_DEFINITION) over (partition by DISTRIBUTION_CHANNEL_HKEY, RECORD_SOURCE order by LOAD_DATETIME) as prev_hashdiff,
           lag(payload_sig) over (partition by DISTRIBUTION_CHANNEL_HKEY, RECORD_SOURCE order by LOAD_DATETIME) as prev_payload_sig
      from base
)
select 'MAXIMUS' as project, 'SAT_CHANNEL_DEFINITION' as satellite,
       count(*) as versions,
       count_if(HASHDIFF_CHANNEL_DEFINITION = prev_hashdiff) as unchanged_reinserts,
       count_if(payload_sig = prev_payload_sig) as unchanged_payload_reinserts,
       array_slice(array_agg(iff(HASHDIFF_CHANNEL_DEFINITION = prev_hashdiff or payload_sig = prev_payload_sig, to_varchar(DISTRIBUTION_CHANNEL_HKEY, 'HEX'), null))
                   within group (order by DISTRIBUTION_CHANNEL_HKEY), 0, 3) as examples,
       iff(unchanged_reinserts = 0 and unchanged_payload_reinserts = 0, 'PASS', 'FAIL') as status
  from seq;



