-- [5 col(s)]. OBJECT satellite: MOBILENUMBER hold one entry per source table (sat value
-- = col:"<TABLE>"; expected = MAX over that table's RAW rows, as the macro does). Plain
-- columns are MAX across all tables and are not compared per table. A table absent from
-- the latest incremental window is absent from the latest row -- compare after a full
-- load.
----------------------------------------------------------------------------------------
with base as (
    select PARTY_HKEY, RECORD_SOURCE, LOAD_DATETIME, HASHDIFF,
           md5(to_json(object_construct_keep_null('ALTERNATEEMAILADDRESS', ALTERNATEEMAILADDRESS, 'ALTERNATEMOBILENUMBER', ALTERNATEMOBILENUMBER, 'EMAILADDRESS', EMAILADDRESS, 'FAXNUMBER', FAXNUMBER, 'LANDLINENUMBER', LANDLINENUMBER, 'MOBILENUMBER', MOBILENUMBER, 'SOCIALMEDIAHANDLE', SOCIALMEDIAHANDLE, 'STDCODE', STDCODE))) as payload_sig
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_COMMON_CONTACT
     where RECORD_SOURCE = 'MAXIMUS'
),
seq as (
    select *,
           lag(HASHDIFF) over (partition by PARTY_HKEY, RECORD_SOURCE order by LOAD_DATETIME) as prev_hashdiff,
           lag(payload_sig) over (partition by PARTY_HKEY, RECORD_SOURCE order by LOAD_DATETIME) as prev_payload_sig
      from base
)
select 'MAXIMUS' as project, 'SAT_COMMON_CONTACT' as satellite,
       count(*) as versions,
