-- 11. MAXIMUS — SAT_LNK_PARTY_ROLE_CORE   [Implemented]
-- Multi-active: a version is the whole member set loaded at one LOAD_DATETIME; two
-- consecutive identical sets = an unchanged group was re-inserted. standard satellite,
-- ma_sat_multi_source; PK PARTY_HKEY, child key ROLECODE, ROLESEQUENCE; 4 RECORD_SOURCE
-- group(s):
-- MAXIMUS_BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_MULTI_SET_PROPERTY_MULTI_SET_DETAIL_PROPERTY_PIVOT_VW
-- [1 col(s)],
-- MAXIMUS_BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW
-- [3 col(s)], MAXIMUS_BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_RELATION [2 col(s)],
-- MAXIMUS_BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_RELATED_PARTY [1 col(s)]. Multi-active:
-- compared per (key, child key); latest = max LOAD_DATETIME per member.
----------------------------------------------------------------------------------------
with grp as (  -- one signature per loaded group (key, RECORD_SOURCE, LOAD_DATETIME)
    select PARTY_HKEY, RECORD_SOURCE, LOAD_DATETIME,
           listagg(to_varchar(ROLECODE) || to_varchar(ROLESEQUENCE) || ':' || to_varchar(HASHDIFF, 'HEX'), ',')
               within group (order by ROLECODE, ROLESEQUENCE, HASHDIFF) as sig
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_LNK_PARTY_ROLE_CORE
