    select PARTY_HKEY, RECORD_SOURCE, LOAD_DATETIME, HASHDIFF,
           md5(to_json(object_construct_keep_null('AADHAARNUMBER', AADHAARNUMBER, 'AADHAARVERIFICATIONSTATUS', AADHAARVERIFICATIONSTATUS, 'AGEPROOFTYPE', AGEPROOFTYPE, 'CINNUMBER', CINNUMBER, 'CKYCNUMBER', CKYCNUMBER, 'DRIVINGLICENCEEXPIRYDATE', DRIVINGLICENCEEXPIRYDATE, 'DRIVINGLICENCENUMBER', DRIVINGLICENCENUMBER, 'EIANUMBER', EIANUMBER, 'FORM60INDICATOR', FORM60INDICATOR, 'GSTIN', GSTIN, 'GSTREGISTRATIONSTATUS', GSTREGISTRATIONSTATUS, 'GSTTAXPAYERTYPE', GSTTAXPAYERTYPE, 'IDENTIFICATIONEXPIRYDATE', IDENTIFICATIONEXPIRYDATE, 'IDENTIFICATIONISSUEDATE', IDENTIFICATIONISSUEDATE, 'IDENTIFICATIONISSUINGAUTHORITY', IDENTIFICATIONISSUINGAUTHORITY, 'IDENTIFICATIONNUMBER', IDENTIFICATIONNUMBER, 'IDENTIFICATIONTYPECODE', IDENTIFICATIONTYPECODE, 'IDENTIFICATIONVERIFIEDINDICATOR', IDENTIFICATIONVERIFIEDINDICATOR, 'INSURANCEREPOSITORYNAME', INSURANCEREPOSITORYNAME, 'NREGACARDNUMBER', NREGACARDNUMBER, 'OVDCATEGORY', OVDCATEGORY, 'PANNUMBER', PANNUMBER, 'PANVERIFICATIONSTATUS', PANVERIFICATIONSTATUS, 'PASSPORTEXPIRYDATE', PASSPORTEXPIRYDATE, 'PASSPORTNUMBER', PASSPORTNUMBER, 'TANNUMBER', TANNUMBER, 'VOTERIDNUMBER', VOTERIDNUMBER))) as payload_sig
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_PARTY_IDENTIFICATION
     where RECORD_SOURCE = 'MAXIMUS'
),
seq as (
    select *,
           lag(HASHDIFF) over (partition by PARTY_HKEY, RECORD_SOURCE order by LOAD_DATETIME) as prev_hashdiff,
