-- [14 col(s)].
----------------------------------------------------------------------------------------
with base as (
    select PARTY_HKEY, RECORD_SOURCE, LOAD_DATETIME, HASHDIFF,
           md5(coalesce(to_varchar(AGE), '^^') || '||' || coalesce(to_varchar(COUNTRYOFBIRTH), '^^') || '||' || coalesce(to_varchar(COUNTRYOFRESIDENCE), '^^') || '||' || coalesce(to_varchar(DATEOFBIRTH), '^^') || '||' || coalesce(to_varchar(DATEOFDEATH), '^^') || '||' || coalesce(to_varchar(FIRSTNAME), '^^') || '||' || coalesce(to_varchar(GENDERCODE), '^^') || '||' || coalesce(to_varchar(LASTNAME), '^^') || '||' || coalesce(to_varchar(MIDDLENAME), '^^') || '||' || coalesce(to_varchar(NATIONALITY), '^^') || '||' || coalesce(to_varchar(PARTYFULLNAME), '^^') || '||' || coalesce(to_varchar(PARTYLEGALNAME), '^^') || '||' || coalesce(to_varchar(PARTYORIGINATIONDATE), '^^') || '||' || coalesce(to_varchar(PARTYSTATUS), '^^') || '||' || coalesce(to_varchar(PARTYSUBTYPECODE), '^^') || '||' || coalesce(to_varchar(PARTYTYPECODE), '^^') || '||' || coalesce(to_varchar(SALUTATION), '^^') || '||') as payload_sig
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_PARTY_IDENTITY
     where startswith(RECORD_SOURCE, 'MAXIMUS_')
),
seq as (
