           md5(coalesce(to_varchar(ADVANCEAMOUNT), '^^') || '||' || coalesce(to_varchar(ADVANCEPAYMENTAPPLICABLEINDICATOR), '^^') || '||' || coalesce(to_varchar(ADVANCEPAYMENTENDDATE), '^^') || '||' || coalesce(to_varchar(ADVANCEPAYMENTSTARTDATE), '^^') || '||' || coalesce(to_varchar(BANKACCOUNTDETAILTEXT), '^^') || '||' || coalesce(to_varchar(CHARGEFILEREFERENCE), '^^') || '||' || coalesce(to_varchar(CREDITCARDACCEPTEDINDICATOR), '^^') || '||' || coalesce(to_varchar(CREDITLIMITAMOUNT), '^^') || '||' || coalesce(to_varchar(CREDITTERMSDETAIL), '^^') || '||' || coalesce(to_varchar(DEDUCTCLAIMSINDICATOR), '^^') || '||' || coalesce(to_varchar(ZEROCHARGEBACKPROGRAMMEENROLLEDINDICATOR), '^^') || '||') as payload_sig
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_AUG_PROVIDER_BANKING
     where startswith(RECORD_SOURCE, 'MAXIMUS_')
),
seq as (
    select *,
           lag(HASHDIFF_AUG_PROVIDER_BANKING) over (partition by PARTY_HKEY, RECORD_SOURCE order by LOAD_DATETIME) as prev_hashdiff,
           lag(payload_sig) over (partition by PARTY_HKEY, RECORD_SOURCE order by LOAD_DATETIME) as prev_payload_sig
      from base
)
select 'MAXIMUS' as project, 'SAT_AUG_PROVIDER_BANKING' as satellite,
       count(*) as versions,
       count_if(HASHDIFF_AUG_PROVIDER_BANKING = prev_hashdiff) as unchanged_reinserts,
       count_if(payload_sig = prev_payload_sig) as unchanged_payload_reinserts,
       array_slice(array_agg(iff(HASHDIFF_AUG_PROVIDER_BANKING = prev_hashdiff or payload_sig = prev_payload_sig, to_varchar(PARTY_HKEY, 'HEX'), null))
                   within group (order by PARTY_HKEY), 0, 3) as examples,
       iff(unchanged_reinserts = 0 and unchanged_payload_reinserts = 0, 'PASS', 'FAIL') as status
  from seq;



----------------------------------------------------------------------------------------
-- 97. MAXIMUS — SAT_AUG_PROVIDER_QUALITY   [Implemented]
-- Consecutive versions of a key (per RECORD_SOURCE, by LOAD_DATETIME) must differ in
-- HASHDIFF (unchanged_reinserts) AND in the stored payload itself
-- (unchanged_payload_reinserts -- catches a HASHDIFF that hashes columns this satellite
-- does not store, e.g. a shared stage). augmented satellite, automate_dv.sat; PK
-- PARTY_HKEY; 1 RECORD_SOURCE group(s): MAXIMUS_pd_prop_sp_pv [38 col(s)].
----------------------------------------------------------------------------------------
with base as (
    select PARTY_HKEY, RECORD_SOURCE, LOAD_DATETIME, HASHDIFF_AUG_PROVIDER_QUALITY,
           md5(coalesce(to_varchar(ASSESSMENTERRORDESCRIPTION), '^^') || '||' || coalesce(to_varchar(ASSESSMENTREPORTQUALITYSCORE), '^^') || '||' || coalesce(to_varchar(AVERAGEADMISSIONTIME), '^^') || '||' || coalesce(to_varchar(AVERAGEDISCHARGETIME), '^^') || '||' || coalesce(to_varchar(AVERAGELENGTHOFSTAYMEDICALCASES), '^^') || '||' || coalesce(to_varchar(AVERAGELENGTHOFSTAYSURGICALCASES), '^^') || '||' || coalesce(to_varchar(BEDOCCUPANCYRATE), '^^') || '||' || coalesce(to_varchar(CERTIFICATIONNUMBER), '^^') || '||' || coalesce(to_varchar(CERTIFICATIONTYPE), '^^') || '||' || coalesce(to_varchar(CITYSCORE), '^^') || '||' || coalesce(to_varchar(CSECTIONRATE), '^^') || '||' || coalesce(to_varchar(DISCOUNTSCORE), '^^') || '||' || coalesce(to_varchar(DISCREPANCYNOTED), '^^') || '||' || coalesce(to_varchar(EMPANELMENTRECOMMENDATION), '^^') || '||' || coalesce(to_varchar(EVALUATIONLOGINFORMATION), '^^') || '||' || coalesce(to_varchar(EVALUATIONRECOMMENDATION), '^^') || '||' || coalesce(to_varchar(EVALUATIONREPORTREFERENCE), '^^') || '||' || coalesce(to_varchar(ILMREVIEWFEEDBACK), '^^') || '||' || coalesce(to_varchar(ILMREVIEWREMARKS), '^^') || '||' || coalesce(to_varchar(MEDICALRECORDSCODINGPROCEDURE), '^^') || '||' || coalesce(to_varchar(MONTHLYCASEVOLUMEOTHERINDUSTRYDEDICATED), '^^') || '||' || coalesce(to_varchar(MONTHLYCASEVOLUMEOTHERINDUSTRYTOTAL), '^^') || '||' || coalesce(to_varchar(MONTHLYCASEVOLUMEOTHERINSURERDEDICATED), '^^') || '||' || coalesce(to_varchar(MONTHLYCASEVOLUMEOTHERINSURERTOTAL), '^^') || '||' || coalesce(to_varchar(PROACTIVEDECISIONMAKINGSCORE), '^^') || '||' || coalesce(to_varchar(PROVIDERGRADE), '^^') || '||' || coalesce(to_varchar(PROVIDERQUALIFIER), '^^') || '||' || coalesce(to_varchar(QRSEVALUATIONDATE), '^^') || '||' || coalesce(to_varchar(QRSSTATUS), '^^') || '||' || coalesce(to_varchar(QRSTYPE), '^^') || '||' || coalesce(to_varchar(QUALITYCHECKSTAFFCOUNTDEDICATED), '^^') || '||' || coalesce(to_varchar(QUALITYCHECKSTAFFCOUNTTOTAL), '^^') || '||' || coalesce(to_varchar(REGIONALCOORDINATORREMARK), '^^') || '||' || coalesce(to_varchar(REGULARMEDICALAUDITINDICATOR), '^^') || '||' || coalesce(to_varchar(REPAIRERCONDUCTFEEDBACK), '^^') || '||' || coalesce(to_varchar(SITEVISITCONDUCTEDBY), '^^') || '||' || coalesce(to_varchar(SITEVISITCONDUCTEDINDICATOR), '^^') || '||' || coalesce(to_varchar(SITEVISITDATE), '^^') || '||') as payload_sig
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_AUG_PROVIDER_QUALITY
     where startswith(RECORD_SOURCE, 'MAXIMUS_')
),
seq as (
    select *,
           lag(HASHDIFF_AUG_PROVIDER_QUALITY) over (partition by PARTY_HKEY, RECORD_SOURCE order by LOAD_DATETIME) as prev_hashdiff,
           lag(payload_sig) over (partition by PARTY_HKEY, RECORD_SOURCE order by LOAD_DATETIME) as prev_payload_sig
      from base
)
select 'MAXIMUS' as project, 'SAT_AUG_PROVIDER_QUALITY' as satellite,
       count(*) as versions,
       count_if(HASHDIFF_AUG_PROVIDER_QUALITY = prev_hashdiff) as unchanged_reinserts,
       count_if(payload_sig = prev_payload_sig) as unchanged_payload_reinserts,
       array_slice(array_agg(iff(HASHDIFF_AUG_PROVIDER_QUALITY = prev_hashdiff or payload_sig = prev_payload_sig, to_varchar(PARTY_HKEY, 'HEX'), null))
                   within group (order by PARTY_HKEY), 0, 3) as examples,
       iff(unchanged_reinserts = 0 and unchanged_payload_reinserts = 0, 'PASS', 'FAIL') as status
  from seq;



----------------------------------------------------------------------------------------
-- 98. MAXIMUS — SAT_AUG_PROVIDER_TARIFF   [Implemented]
-- Consecutive versions of a key (per RECORD_SOURCE, by LOAD_DATETIME) must differ in
-- HASHDIFF (unchanged_reinserts) AND in the stored payload itself
-- (unchanged_payload_reinserts -- catches a HASHDIFF that hashes columns this satellite
-- does not store, e.g. a shared stage). augmented satellite, automate_dv.sat; PK
-- PARTY_HKEY; 1 RECORD_SOURCE group(s): MAXIMUS_pd_prop_sp_pv [17 col(s)].
----------------------------------------------------------------------------------------
with base as (
    select PARTY_HKEY, RECORD_SOURCE, LOAD_DATETIME, HASHDIFF_AUG_PROVIDER_TARIFF,
           md5(coalesce(to_varchar(DELAYEDSUBMISSIONDISCOUNTAPPLICABLEINDICATOR), '^^') || '||' || coalesce(to_varchar(DISCOUNTANDLOADINGTERMS), '^^') || '||' || coalesce(to_varchar(DISCOUNTTYPE), '^^') || '||' || coalesce(to_varchar(FLATRATEBASISINDICATOR), '^^') || '||' || coalesce(to_varchar(HOSPITALSPECIFICBILLITEMCODE), '^^') || '||' || coalesce(to_varchar(NEGOTIATIONENDDATE), '^^') || '||' || coalesce(to_varchar(NEGOTIATIONREMARKS), '^^') || '||' || coalesce(to_varchar(NEGOTIATIONSTARTDATE), '^^') || '||' || coalesce(to_varchar(PACKAGEACCEPTANCEDATE), '^^') || '||' || coalesce(to_varchar(PACKAGETYPE), '^^') || '||' || coalesce(to_varchar(STEPDOWNAPPLICABLEINDICATOR), '^^') || '||' || coalesce(to_varchar(SURCHARGEPERCENTAGE), '^^') || '||' || coalesce(to_varchar(TARIFFDOCUMENTREFERENCE), '^^') || '||' || coalesce(to_varchar(TARIFFDOCUMENTSAVAILABLEINDICATOR), '^^') || '||' || coalesce(to_varchar(TARIFFLINEREMARKS), '^^') || '||' || coalesce(to_varchar(TARIFFMASTERUPLOADEDINDICATOR), '^^') || '||' || coalesce(to_varchar(TARIFFSTANDARDISEDINDICATOR), '^^') || '||') as payload_sig
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_AUG_PROVIDER_TARIFF
     where startswith(RECORD_SOURCE, 'MAXIMUS_')
),
seq as (
    select *,
           lag(HASHDIFF_AUG_PROVIDER_TARIFF) over (partition by PARTY_HKEY, RECORD_SOURCE order by LOAD_DATETIME) as prev_hashdiff,
           lag(payload_sig) over (partition by PARTY_HKEY, RECORD_SOURCE order by LOAD_DATETIME) as prev_payload_sig
      from base
)
select 'MAXIMUS' as project, 'SAT_AUG_PROVIDER_TARIFF' as satellite,
       count(*) as versions,
       count_if(HASHDIFF_AUG_PROVIDER_TARIFF = prev_hashdiff) as unchanged_reinserts,
       count_if(payload_sig = prev_payload_sig) as unchanged_payload_reinserts,
       array_slice(array_agg(iff(HASHDIFF_AUG_PROVIDER_TARIFF = prev_hashdiff or payload_sig = prev_payload_sig, to_varchar(PARTY_HKEY, 'HEX'), null))
                   within group (order by PARTY_HKEY), 0, 3) as examples,
       iff(unchanged_reinserts = 0 and unchanged_payload_reinserts = 0, 'PASS', 'FAIL') as status
  from seq;



----------------------------------------------------------------------------------------
-- 99. MAXIMUS — CDC result (all satellites)   [Implemented]
-- Joins the BEFORE and AFTER captures of the same run id. raw_changed compares the
-- normalised RAW payload hash (same UPPER/TRIM/NULL rules as the HASHDIFF, so a
-- case-only RAW edit is not a change); new_rows = satellite rows added for the key
-- between the captures.
----------------------------------------------------------------------------------------
with b as (select * from BAGIC_PREPROD_CURATED_DB.BGIL_VALIDATION.DM_H_CDC_SNAPSHOT where run_id = $DM_H_RUN and phase = 'BEFORE' and project = 'MAXIMUS'),
     a as (select * from BAGIC_PREPROD_CURATED_DB.BGIL_VALIDATION.DM_H_CDC_SNAPSHOT where run_id = $DM_H_RUN and phase = 'AFTER'  and project = 'MAXIMUS'),
     k as (
    select b.satellite, b.record_source, b.hkey, b.cdk,
           not equal_null(b.raw_hash, a.raw_hash) as raw_changed,
           a.sat_rows - b.sat_rows as new_rows
      from b join a
        on a.satellite = b.satellite and a.record_source = b.record_source
       and a.hkey = b.hkey and equal_null(a.cdk, b.cdk)
)
select 'MAXIMUS' as project, satellite, record_source,
       count(*) as unchanged_keys,
       count_if(new_rows = 0) as unchanged_no_new_row,
       count_if(new_rows <> 0) as unchanged_with_new_row,
       iff(unchanged_with_new_row = 0, 'PASS', 'FAIL') as status
  from k
 where not raw_changed
 group by satellite, record_source
 order by iff(status = 'FAIL', 0, 1), satellite, record_source;
